fn shade(z: i32) -> i32 {
    let mut b: i32 = 150 + z * 2;
    if b < 50 { b = 50; }
    if b > 255 { b = 255; }
    (b << 16) | (((b * 2) / 3) << 8)
}

fn frame(t: i32) {
    host::display::clear(0x0a0400);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let big: i32 = 52;
    let small: i32 = 22;
    let ca: i32 = host::math::cos(t);
    let sa: i32 = host::math::sin(t);
    let cb: i32 = host::math::cos(t / 3);
    let sb: i32 = host::math::sin(t / 3);
    let mut u: i32 = 0;
    while u < 256 {
        let mut v: i32 = 0;
        while v < 256 {
            let ring: i32 = big + (small * host::math::cos(v)) / 256;
            let x0: i32 = (ring * host::math::cos(u)) / 256;
            let z0: i32 = (ring * host::math::sin(u)) / 256;
            let y0: i32 = (small * host::math::sin(v)) / 256;
            let x1: i32 = (x0 * ca - z0 * sa) / 256;
            let z1: i32 = (x0 * sa + z0 * ca) / 256;
            let y2: i32 = (y0 * cb - z1 * sb) / 256;
            let z2: i32 = (y0 * sb + z1 * cb) / 256;
            let depth: i32 = z2 + 260;
            let px: i32 = cx + (x1 * 300) / depth;
            let py: i32 = cy + (y2 * 300) / depth;
            host::display::fill_rect(px, py, 2, 2, shade(z2));
            v = v + 16;
        }
        u = u + 6;
    }
    host::display::present();
}
